// Only process rows explicitly marked active, and normalise field names/
// defaults so a client row with blank threshold columns still works.
const rows = $input.all().map(item => item.json);

return rows
  .filter(r => String(r.active || '').trim().toLowerCase() !== 'no' && String(r.active || '').trim().toLowerCase() !== 'false')
  .map(r => ({
    json: {
      client_name: String(r.client_name || '').trim(),
      ad_account_id: String(r.ad_account_id || '').trim(), // expects the 'act_XXXXXXXXXX' format
      sheet_tab: String(r.sheet_tab || r.client_name || '').trim(),
      slack_channel_url: String(r.slack_channel_url || '').trim(),
      // Defaults if a client row leaves these blank — see README for how
      // these are actually used in the alert-check step further down.
      spend_spike_pct: parseFloat(r.spend_spike_pct) || 50,
      cpl_double_threshold: parseFloat(r.cpl_double_threshold) || 2.0
    }
  }));

// Merge campaign/adset/ad insights + ad statuses into one flat, normalised
// row-per-entity list for this client, ready to append to their sheet tab.
const client = $('Loop Over Clients').item.json;
const campaignResp = $('Fetch Campaign Insights').first().json;
const adsetResp = $('Fetch AdSet Insights').first().json;
const adResp = $('Fetch Ad Insights').first().json;
const statusResp = $('Fetch Ad Statuses').first().json;

const today = new Date().toISOString().slice(0, 10);

// Meta returns costs/results nested inside `actions` / `cost_per_action_type`
// arrays keyed by action_type, not flat fields — pull out a lead-ish action.
// Ad accounts vary in which action_type represents "a lead" for them
// (lead form vs offsite pixel vs on-Facebook conversion) — this checks the
// common ones in order and falls back gracefully if none match.
const LEAD_ACTION_TYPES = ['lead', 'onsite_conversion.lead_grouped', 'offsite_conversion.fb_pixel_lead'];

function findAction(actions, types) {
  if (!Array.isArray(actions)) return null;
  for (const t of types) {
    const match = actions.find(a => a.action_type === t);
    if (match) return match;
  }
  return null;
}

function rowFromInsight(insight, level) {
  const resultAction = findAction(insight.actions, LEAD_ACTION_TYPES);
  const results = resultAction ? Number(resultAction.value) : 0;
  const spend = Number(insight.spend) || 0;
  const costPerResult = results > 0 ? spend / results : null;

  const roasEntry = Array.isArray(insight.purchase_roas) ? insight.purchase_roas[0] : null;
  const roas = roasEntry ? Number(roasEntry.value) : null;

  return {
    date: today,
    client_name: client.client_name,
    level,
    entity_id: (level === 'campaign' ? insight.campaign_id : level === 'adset' ? insight.adset_id : insight.ad_id) || '',
    entity_name: (level === 'campaign' ? insight.campaign_name : level === 'adset' ? insight.adset_name : insight.ad_name) || '',
    campaign_id: insight.campaign_id || '',
    adset_id: insight.adset_id || '',
    ad_id: insight.ad_id || '',
    spend,
    impressions: Number(insight.impressions) || 0,
    clicks: Number(insight.clicks) || 0,
    cpm: Number(insight.cpm) || 0,
    cpc: Number(insight.cpc) || 0,
    ctr: Number(insight.ctr) || 0,
    frequency: Number(insight.frequency) || 0,
    results,
    cost_per_result: costPerResult,
    roas,
    effective_status: ''
  };
}

const campaignRows = (campaignResp.data || []).map(i => rowFromInsight(i, 'campaign'));
const adsetRows = (adsetResp.data || []).map(i => rowFromInsight(i, 'adset'));
const adRows = (adResp.data || []).map(i => rowFromInsight(i, 'ad'));

// Attach effective_status onto the matching ad-level rows so the alert-check
// step downstream can flag any DISAPPROVED / rejected ad.
const statusById = new Map((statusResp.data || []).map(a => [a.id, a.effective_status]));
for (const row of adRows) {
  row.effective_status = statusById.get(row.ad_id) || '';
}

const allRows = [...campaignRows, ...adsetRows, ...adRows];

// n8n stops a branch dead when a node outputs zero items, which would
// silently skip logging/reporting/alerting entirely on a day with no
// campaign activity. Emit one explicit marker row instead so the rest of
// the chain always runs, and the sheet has an honest record of "nothing
// happened" rather than a gap.
if (allRows.length === 0) {
  return [{
    json: {
      date: today,
      client_name: client.client_name,
      level: 'none',
      entity_id: '',
      entity_name: 'No data returned from Meta for this period',
      campaign_id: '',
      adset_id: '',
      ad_id: '',
      spend: 0,
      impressions: 0,
      clicks: 0,
      cpm: 0,
      cpc: 0,
      ctr: 0,
      frequency: 0,
      results: 0,
      cost_per_result: null,
      roas: null,
      effective_status: '',
      ...client
    }
  }];
}

return allRows.map(row => ({ json: { ...row, ...client } }));

// Compute week-over-week deltas per entity_id, and flag alert-worthy
// conditions: spend spikes, CPL doubling, and any rejected ad.
const allRows = $input.all().map(item => item.json);
const client = $('Loop Over Clients').item.json;

const today = new Date().toISOString().slice(0, 10);
const todayRows = allRows.filter(r => r.date === today);

const sevenDaysAgo = new Date();
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
const weekAgoDate = sevenDaysAgo.toISOString().slice(0, 10);

const enriched = todayRows.map(row => {
  const prior = allRows.find(r => r.date === weekAgoDate && r.entity_id === row.entity_id && r.level === row.level);
  const priorSpend = prior ? Number(prior.spend) : null;
  const priorCpl = prior && prior.cost_per_result ? Number(prior.cost_per_result) : null;

  const spendChangePct = priorSpend && priorSpend > 0
    ? ((row.spend - priorSpend) / priorSpend) * 100
    : null;
  const cplRatio = priorCpl && row.cost_per_result
    ? row.cost_per_result / priorCpl
    : null;

  return {
    ...row,
    prior_spend: priorSpend,
    spend_change_pct: spendChangePct,
    prior_cost_per_result: priorCpl,
    cpl_ratio_vs_last_week: cplRatio,
    // Ad fatigue heuristic: frequency climbing while CTR is falling is the
    // classic "same people seeing it too often, getting tired of it" signal.
    // This is a starting heuristic, not a precise model -- tune thresholds
    // against real client data once available.
    fatigue_flag: row.frequency > 3 && row.ctr < 1,
    spend_spike_flag: spendChangePct !== null && spendChangePct >= client.spend_spike_pct,
    cpl_doubled_flag: cplRatio !== null && cplRatio >= client.cpl_double_threshold,
    rejected_flag: String(row.effective_status || '').toUpperCase().includes('DISAPPROV')
  };
});

const anyAlert = enriched.some(r => r.spend_spike_flag || r.cpl_doubled_flag || r.rejected_flag);

return [{
  json: {
    client_name: client.client_name,
    slack_channel_url: client.slack_channel_url,
    rows: enriched,
    any_alert: anyAlert
  }
}];

