=:rotating_light: *Alert for {{ $json.client_name }}*

{{ $json.rows.filter(r => r.spend_spike_flag).map(r => `• Spend spike: *${r.entity_name}* up ${r.spend_change_pct.toFixed(0)}% vs last week ($${r.prior_spend.toFixed(2)} → $${r.spend.toFixed(2)})`).join('\n') }}
{{ $json.rows.filter(r => r.cpl_doubled_flag).map(r => `• CPL doubled: *${r.entity_name}* $${r.prior_cost_per_result.toFixed(2)} → $${r.cost_per_result.toFixed(2)}`).join('\n') }}
{{ $json.rows.filter(r => r.rejected_flag).map(r => `• Ad rejected: *${r.entity_name}*`).join('\n') }}
